ANAGE','Admin','จัดการผู้ใช้งาน มอบหรือถอดถอนตำแหน่ง/สิทธิ์ในคณะ (CRUD)'),(26,'DATA_IMPORT_EXPORT','Admin','นำเข้าและส่งออกข้อมูลเชิงระบบเข้าสู่ฐานข้อมูลหลัก'),(27,'ADMIN_APPROVALS','Admin','ตรวจสอบและกดอนุมัติคำขอสิทธิ์การดูแลต่างๆ ย้อนหลัง'),(28,'AUDIT_LOG_VIEW','Admin','ดูบันทึกและประวัติกิจกรรมการใช้งานระบบ (Audit Log)'),(29,'ADMIN_REPORTS','Admin','สร้างรายงานเชิงสรุปข้อมูลเสนอผู้บริหาร'),(30,'ASSIGN_INSTRUCTORS','Curriculum','มอบหมายรายชื่ออาจารย์ผู้สอนหลักในแต่ละรายวิชา'),(31,'PROJECT_MY_VIEW','Project','ดูรายการโครงการย่อยที่ตนเองรับผิดชอบ'),(32,'PROJECT_DOCS_MANAGE','Project','จัดการอัปโหลดเอกสารภายในโครงการ'),(33,'PROJECT_LINKS_MANAGE','Project','จัดการข้อมูลลิงก์และความเชื่อมโยงระดับ LO'),(34,'PROJECT_REPORTS_VIEW','Project','เข้าถึงและเรียกดูรายงานสรุปผลโครงการ'),(35,'VIEW_RETENTION','Executive','ดูอัตราการคงอยู่และสาเหตุการออกของนักศึกษา'),(36,'STUDENT_VIEW_TRANSCRIPT',NULL,'นักศึกษาดูข้อมูลของตัวเอง');
