INSERT INTO `subject` VALUES (1,'103-111','ภาษาอังกฤษพื้นฐาน','English Fundamentals',3,'3(2-2-5)','การอ่านข้อความที่สั้นและง่าย การฝึกใช้คำศัพท์และสำนวนพื้นฐานในการสนทนา การทำตามคำแนะนำ ความเข้าใจข้อมูลในโฆษณา โปรแกรม และโบรชัวร์ การสร้างวลีและประโยคอย่างง่ายในงานเขียน การอธิบายตนเองและชีวิตประจำวัน การเขียนข้อความสั้นๆ การโพสต์ออนไลน์ การมีส่วนร่วมอย่างแข่งขันในการถามและตอบคำถาม การมีส่วนร่วมในการสนทนาในหัวข้อที่ไม่ซับซ้อน',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',1,1),(2,'103-112','การสื่อสารภาษาอังกฤษในชีวิตประจำวัน','English Communication in Everyday Life',3,'3(2-2-5)','การสื่อสารอย่างมั่นใจในสถานการณ์ที่กำหนดไว้ การแลกเปลี่ยนความคิดเห็น การถามและตอบคำถามในหัวข้อที่คุ้นเคย การมีส่วนร่วมในการสนทนาที่เกี่ยวข้องกับความสนใจและสาขาวิชาชีพ การอธิบายและชี้แจง การสื่อสารกับผู้อื่น เช่น การขอความช่วยเหลือ การเสนอแนะ และการปฏิบัติตามคำแนะนำ การเขียนจดหมายโต้ตอบเพื่อการสื่อสาร การใช้แพลตฟอร์มออนไลน์เพื่อการสื่อสาร',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',1,2),(3,'103-113','ภาษาอังกฤษเพื่อการศึกษาทางวิชาการ','English for Academic Study',3,'3(2-2-5)','การฝึกทักษะภาษาอังกฤษทั้ง 4 ด้านเพื่อการศึกษาทางวิชาการ การฟัง และตอบคำถามทางวิชาการ การนำเสนอด้วยปากเปล่า การพัฒนาความเข้าใจในการอ่านและทักษะการอ่านอย่างมีวิจารณญาณ คำศัพท์ และโครงสร้างประโยคที่ใช้ในการเขียนทางวิชาการ การเขียนย่อหน้าประเภทต่างๆ',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(4,'103-114','ภาษาอังกฤษเพื่อการนำเสนอแบบมืออาชีพ','English for Professional Presentation',3,'3(2-2-5)','หลักการพูด การเลือกใช้คำ ประโยค คำเชื่อมและสำนวน การพูดในสถานการณ์ต่างๆ การแสดงความคิดเห็นและการนำเสนอเชิงวิชาการ การนำเสนอทางธุรกิจ การสัมภาษณ์งาน',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(5,'103-121','ภาษาไทยเพื่อการสื่อสาร','Thai Language for Communication',3,'3(2-2-5)','ภาษาไทยเพื่อการสื่อสารในสถานการณ์ต่างๆ หลักการใช้ภาษาสื่อสารที่ถูกต้องทั้งการรับสารและส่งสาร การจับประเด็นและการวิเคราะห์สารจากเรื่องที่ฟังหรืออ่านอย่างมีวิจารณญาณและนำเสนอความคิดผ่านการพูดการเขียนในรูปแบบที่เหมาะสมได้อย่างมีประสิทธิภาพ',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(6,'103-122','ภาษาไทยเพื่อการนำเสนอ','Thai Language for Presentation',3,'3(2-2-5)','การใช้ภาษาไทยนําเสนอข้อมูลในสถานการณ์ต่างๆ อาทิ การนําเสนอข้อมูลทางวิชาการ การนําเสนอข้อมูลทางธุรกิจ การแสดงความคิดเห็น วิเคราะห์และวิจารณ์ การนําเสนอข้อมูลที่มีความน่าเชื่อถือ การเลือกใช้ช่องทางการสื่อสารอย่างเหมาะสม และมีประสิทธิภาพเป็นประโยชน์ต่อการศึกษาและการทํางาน',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(7,'103-123','ภาษาไทยเพื่อผู้ประกอบการ','Thai Language for Entrepreneurs',3,'3(2-2-5)','ภาษาไทยเพื่อการทำงานในสถานประกอบการ ทักษะการสื่อสารภาษาไทยที่มีประสิทธิภาพและจำเป็นต่อการทำงานในองค์กรทั้งการฟัง การพูด การอ่าน และการเขียน การจัดทำเอกสารการประชุมหรือเอกสารที่เกี่ยวข้องกับการทำงาน',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(8,'103-131','ภาษาจีนเพื่อการสื่อสารในชีวิตประจำวัน','Chinese for Daily Communication',3,'3(2-2-5)','การฝึกทักษะฟัง พูด อ่าน และเขียน วิธีการอ่านสัทอักษรการถอดเสียงพินอิน Pinyin ภาษาจีนกลางที่ถูกต้อง โครงสร้างไวยากรณ์ คำศัพท์ประมาณ 150-300 คำ และสำนวนพื้นฐานที่ใช้ในชีวิตประจำวัน บทสนทนาขั้นพื้นฐาน ได้แก่ การพูดสนทนาทักทาย การแนะนำตนเอง การนับ และการใช้ตัวเลขแสดงจำนวน การสอบถามสถานที่และตำแหน่งทิศทาง การบอกเวลา และการบอกชื่อสิ่งของ',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(9,'103-141','ภาษาญี่ปุ่นในชีวิตประจำวัน','Daily Life Japanese',3,'3(2-2-5)','คำศัพท์ สำนวน วัฒนธรรม และทักษะในการสื่อสาร การตั้งคำถามและการตอบอย่างสั้น บทสนทนาอย่างง่ายในระดับวลี และประโยคสั้นๆโดยเน้นหัวข้อที่สามารถประยุกต์ใช้ในชีวิตประจำวัน',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(10,'103-151','การเขียนโค้ดคอมพิวเตอร์สำหรับทุกคน','Computer Coding for Everyone',3,'3(2-2-5)','ความรู้พื้นฐานการเขียนโปรแกรมด้วยภาษาไพธอน เครื่องมือที่ใช้ในการเขียนโปรแกรมภาษาไพธอน ชนิดของข้อมูลและตัวแปร การรับข้อมูลเข้าและการแสดงผลลัพธ์ การใช้งานคำสั่งทางเลือก การใช้งานคำสั่งวนลูป การสร้างฟังก์ชัน การวิเคราะห์ข้อมูลและการนำเสนอข้อมูล',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(11,'103-201','ทักษะดิจิทัลสำหรับศตวรรษที่ 21','Digital Literacy for 21st Century',3,'3(2-2-5)','การใช้เทคโนโลยีดิจิทัลเพื่อการสืบค้นสารสนเทศ การสื่อสาร และการรู้เท่าทันการเปลี่ยนแปลงด้านเทคโนโลยีดิจิทัล หลักการการเป็นพลเมืองดิจิทัล ความปลอดภัยด้านสารสนเทศ จริยธรรมและกฎหมายที่เกี่ยวข้อง การนำเทคโนโลยีมาใช้เพื่อการจัดการสมัยใหม่ การวิเคราะห์และสังเคราะห์สารสนเทศ การเขียนรายงาน การเลือกเครื่องมือดิจิทัลที่สอดคล้องกับการทำงานเพื่อให้เกิดประสิทธิภาพ',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',1,1),(12,'103-202','การวิเคราะห์ข้อมูลและการเรียนรู้ของเครื่องจักรเบื้องต้น','Introduction to Data Analytics and Machine Learning',3,'3(2-2-5)','พื้นฐานของการทำงานอัตโนมัติ การวิเคราะห์ข้อมูลและการเรียนรู้ของเครื่อง เช่น การรวบรวมข้อมูล การระบุแหล่งข้อมูล การทำความสะอาดข้อมูล การวิเคราะห์ การสื่อสารข้อมูลเชิงลึกด้วยการใช้แดชบอร์ด การแสดงภาพเพื่อเพิ่มมูลค่าให้กับการตัดสินใจ การเรียนรู้ของเครื่องจักร เครื่องมือต่างๆและการประยุกต์ใช้ การอภิปรายสถานการณ์จริงของการเรียนรู้เครื่องมือหรือตัวอย่างของการใช้ปัญญาประดิษฐ์เชิงกำเนิด',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',1,2),(13,'103-203','ความเป็นพลเมืองในสังคมไทยและสังคมโลก','Civic Literacy in Thai and Global Context',3,'3(3-0-6)','สภาพการณ์ทางการเมือง เศรษฐกิจ สังคม และวัฒนธรรมของกลุ่มประเทศต่างๆ ประเด็นปัญหาร่วมสมัยในสังคมโลก ประเทศไทยในสังคมโลก ความหลากหลายทางวัฒนธรรมและกระบวนการทางความคิดที่เป็นสากล ความรับผิดชอบต่อสังคม การรู้หน้าที่ของพลเมืองและรับผิดชอบต่อสังคมในการต่อต้านการทุจริต ความสัมพันธ์ระหว่างความเป็นพลเมืองกับสถานะการพัฒนาของประเทศภายใต้กฎหมายในชีวิตประจำวันและกติกาสากลของสังคมประชาธิปไตย บทบาทและหน้าที่ของบุคคลในฐานะพลเมืองไทยและพลเมืองโลก',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(14,'103-204','มนุษยสัมพันธ์และการพัฒนาบุคลิกภาพ','Human Relations and Personality Development',3,'3(3-0-6)','การสร้างความสัมพันธ์ระหว่างบุคคล การรู้จักตนเองและผู้อื่น เสริมสร้างการเห็นคุณค่าในตนเอง กำหนดเป้าหมายในการเรียนการทำงานและการมีบุคลิกภาพที่เหมาะสม สามารถทำงานร่วมกับผู้อื่นได้',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(15,'103-205','จิตวิทยาในชีวิตประจำวัน','Psychology in Daily Life',3,'3(3-0-6)','แนวคิดทางจิตวิทยาที่สำคัญ พัฒนาการวัยต่างๆ การรับรู้ การจูงใจ บุคลิกภาพและความแตกต่างระหว่างบุคคล ความหลากหลายทางเพศ อิทธิพลทางสังคมและพฤติกรรมทางสังคม การวิเคราะห์ปฏิสัมพันธ์ระหว่างบุคคล ความสัมพันธ์ที่ดี การจัดการความเครียด ความผิดปกติทางจิตและการบำบัด',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(16,'103-206','อาหาร การดูแลสุขภาพ และการออกกำลังกาย','Diet, Health Care and Exercise',3,'3(2-2-5)','สุขภาวะด้านร่างกาย จิตใจ อารมณ์ และสังคม อาหารและโภชนาการ การป้องกันและการบำบัดโรค ด้วยอาหาร ความปลอดภัยของอาหาร ฉลากโภชนาการ ผลิตภัณฑ์เสริมอาหารและการเลือกใช้ การออกกำลังกายเพื่อเสริมสร้างสมรรถภาพของร่างกาย ผลของการออกกำลังกายที่มีต่อระบบต่างๆในร่างกาย นวัตกรรมอาหารเพื่อสุขภาพ และเทคโนโลยีดิจิทัลเพื่อการออกกำลังกาย',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(17,'103-207','สารเคมีในชีวิตประจำวัน','Chemicals in Daily Life',3,'3(3-0-6)','สารเคมีที่ใช้ในชีวิตประจำวัน องค์ประกอบของสารเคมี สารเคมีประเภทธรรมชาติและสารสังเคราะห์ ที่เกี่ยวข้องกับชีวิตประจำวัน น้ำและเครื่องดื่ม สารปรุงแต่งอาหาร ความหมาย ประเภทและสารประกอบของเครื่อง สมอาง ความหมาย ประเภทและสมบัติของสารทำความสะอาด การป้องกันและการแก้พิษจากสารเคมี',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(18,'103-208','คณิตศาสตร์และสถิติในชีวิตประจำวัน','Mathematics and Statistics in Daily Life',3,'3(3-0-6)','คณิตศาสตร์และสถิติเบื้องต้น เพื่อนำไปใช้ในชีวิตประจำวัน โดยใช้ความรู้เรื่อง เรขาคณิต อัตราส่วน ร้อยละ ฟังก์ชัน ความรู้เบื้องต้นเกี่ยวกับสถิติ การเก็บรวบรวมข้อมูล การวิเคราะห์ข้อมูลด้วยสถิติแบบบรรยาย ความน่าจะเป็นกับการตัดสินใจอย่างง่าย',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(19,'103-209','ศิลปะและดนตรีเพื่อสุนทรียภาพแห่งชีวิต','Art and Music Appreciation',3,'3(3-0-6)','ความรู้เกี่ยวกับสุนทรียศาสตร์ ศิลปะในรูปแบบของสถาปัตยกรรม จิตรกรรม ประติมากรรม นาฎศิลป์ และดุริยางคศิลป์ ยุคสมัยต่างๆของศิลปะ แรงบันดาลใจเบื้องหลังผลงานศิลปะ ความซาบซึ้งในศิลปะ การประเมินคุณค่าทางสุนทรียะ ความสัมพันธ์ระหว่างศิลปะ ดนตรี กับชีวิต ศิลปะในชีวิตประจำวัน และคุณค่าความงามในงานศิลปะแขนงต่างๆ ในฐานะเป็นเครื่องมือจรรโลงจิตใจและสร้างสุนทรียภาพต่อชีวิตของมนุษย์',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(20,'103-210','นิยมไทยและอัศจรรย์ในสยาม','Thai Appreciation and Unseen in Siam',3,'3(3-0-6)','ศิลปะและวัฒนธรรม ขนบธรรมเนียมประเพณี เอกลักษณ์ความเป็นไทย มรดกทางภูมิปัญญาที่มีคุณค่า และน่าภาคภูมิใจ คติความเชื่อ ค่านิยม วิถีชีวิต แนวทางการอนุรักษ์ สืบทอดและเผยแพร่ความเป็นไทย',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(21,'103-211','การคิดเชิงสร้างสรรค์และการแก้ปัญหา','Creative Thinking and Problem Solving',3,'3(2-2-5)','กระบวนการคิดและเทคนิคการคิดสร้างสรรค์ในรูปแบบต่างๆ การค้นหาแนวทางหรือทางเลือกใหม่ๆในการทำงาน การวิเคราะห์ปัญหาและการใช้เครื่องมือช่วยในการตัดสินใจเลือกทางเลือกที่มีประสิทธิภาพสูงสุด',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(22,'103-212','การเป็นผู้ประกอบการและการสร้างธุรกิจใหม่','Entrepreneurship and New Business Creation',3,'3(2-2-5)','คุณลักษณะและแนวคิดการเป็นผู้ประกอบการ โอกาสทางธุรกิจ การวิเคราะห์สภาพแวดล้อมทางธุรกิจ การวางแผนกลยุทธ์ การตลาด การเงิน และการจัดการสําหรับธุรกิจใหม่ การจัดทำแผนธุรกิจเบื้องต้น',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(23,'103-301','หลักปรัชญาของเศรษฐกิจพอเพียงเพื่อการพัฒนาที่ยั่งยืน','Philosophy of Sufficiency Economy for Sustainable Development',3,'3(3-0-6)','ความเป็นมาและความหมายของปรัชญาของเศรษฐกิจพอเพียงตามแนวพระราชดำริ การประยุกต์ใช้ในระดับบุคคล ครอบครัว และชุมชน การขับเคลื่อนเศรษฐกิจพอเพียงในภาคส่วนต่างๆของสังคมและการเชื่อมโยงสู่การพัฒนาที่ยั่งยืน',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(24,'103-302','การออกแบบการคิดเพื่อสร้างนวัตกรรมและธุรกิจใหม่','Design Thinking for Innovation and New Business Creation',3,'3(2-2-5)','กระบวนการคิดเชิงออกแบบและการนำมาประยุกต์ใช้ในการระบุปัญหาและสร้างสรรค์นวัตกรรมด้านผลิตภัณฑ์ บริการ หรือโมเดลธุรกิจใหม่ๆ การทดสอบแนวคิดกับกลุ่มเป้าหมายและการพัฒนาเป็นต้นแบบธุรกิจ',1,1,NULL,'หมวดวิชาศึกษาทั่วไป',0,0),(25,'170-108','ชีวเคมี','Biochemistry',2,'2(2-0-4)','โครงสร้างและหน้าที่ของสารชีวโมเลกุลในร่างกายมนุษย์ เอนไซม์และฮอร์โมนที่ควบคุมเมแทบอลิซึม การสลายสารอาหารและการเก็บสะสมพลังงานในระดับเซลล์ ความพยาธิสภาพที่เกิดจากความผิดปกติทางชีวเคมี',1,1,NULL,'หมวดวิชาเฉพาะ',1,1),(26,'170-112','กายวิภาคศาสตร์และสรีรวิทยาของมนุษย์ 1','Human Anatomy and Physiology 1',3,'3(2-2-5)','โครงสร้างและหน้าที่ของร่างกายมนุษย์ในระดับเซลล์และเนื้อเยื่อ ระบบปกคลุมร่างกาย ระบบโครงร่าง ระบบกล้ามเนื้อ ระบบประสาท และระบบรับความรู้สึก กลไกการรักษาดุลยภาพของร่างกายและการฝึกปฏิบัติการที่เกี่ยวข้อง',1,1,NULL,'หมวดวิชาเฉพาะ',1,1),(27,'170-113','กายวิภาคศาสตร์และสรีรวิทยาของมนุษย์ 2','Human Anatomy and Physiology 2',3,'3(2-2-5)','โครงสร้างและหน้าที่ของระบบอวัยวะต่างๆ ต่อเนื่องจากภาค 1 ได้แก่ ระบบไหลเวียนโลหิต ระบบภูมิคุ้มกัน ระบบหายใจ ระบบย่อยอาหาร ระบบขับถ่ายปัสสาวะ ระบบต่อมไร้ท่อ และระบบสืบพันธุ์ รวมถึงการฝึกปฏิบัติการ',1,1,NULL,'หมวดวิชาเฉพาะ',1,2),(28,'170-116','การดูแลสุขภาพแบบผสมผสาน','Alternative and Complementary Health Care',2,'2(2-0-4)','แนวคิดและขอบเขตของการแพทย์ทางเลือกและการแพทย์ผสมผสาน สมาธิบำบัด วารีบำบัด การนวดไทย และศาสตร์ทางเลือกอื่นๆ เพื่อนำมาใช้ในการส่งเสริมสุขภาพและบรรเทาอาการเจ็บป่วยร่วมกับการแพทย์แผนปัจจุบัน',1,1,NULL,'หมวดวิชาเฉพาะเลือก',1,2),(29,'170-117','การดูแลสุขภาพความงามแบบองค์รวม','Holistic Beauty and Wellness Care',2,'2(2-0-4)','แนวคิดและหลักการดูแลสุขภาพความงามจากภายในสู่ภายนอก โภชนาการเพื่อความงาม สารต้านอนุมูลอิสระ การดูแลผิวพรรณ รูปร่าง และการชะลอวัยด้วยวิธีธรรมชาติและการแพทย์สมัยใหม่อย่างปลอดภัย',1,1,NULL,'หมวดวิชาเฉพาะเลือก',1,2),(30,'170-201','พยาธิสรีรวิทยาของมนุษย์','Human Pathophysiology',2,'2(2-0-4)','กลไกการเกิดโรคและความเปลี่ยนแปลงทางสรีรวิทยาในภาวะเจ็บป่วย พยาธิสภาพของโรคที่พบบ่อยในระบบอวัยวะต่างๆ การตอบสนองของเซลล์ต่อการบาดเจ็บ การอักเสบ และกลไกการปรับตัวของร่างกาย',1,1,NULL,'หมวดวิชาเฉพาะ',2,1),(31,'170-208','จุลชีววิทยาและปรสิตวิทยาของมนุษย์','Human Microbiology and Parasitology',2,'2(1-2-3)','คุณลักษณะ กลไกการก่อโรค และการแพร่กระจายของเชื้อแบคทีเรีย ไวรัส เชื้อรา และปรสิตที่ก่อโรคในมนุษย์ ปฏิกิริยาภูมิคุ้มกันของร่างกาย หลักการควบคุมเชื้อและการทำลายเชื้อและการฝึกปฏิบัติการ',1,1,NULL,'หมวดวิชาเฉพาะ',2,1),(32,'170-211','การพยาบาลพื้นฐาน 1','Fundamentals of Nursing 1',3,'3(2-2-5)','แนวคิดพื้นฐานทางการพยาบาล กระบวนการพยาบาล หลักการตอบสนองความต้องการขั้นพื้นฐานด้านความสุขสบาย สุขอนามัย และความปลอดภัยของผู้ป่วย การควบคุมการติดเชื้อในโรงพยาบาล และการฝึกปฏิบัติในห้องปฏิบัติการ',1,1,NULL,'หมวดวิชาเฉพาะ',2,1),(33,'170-212','การพยาบาลพื้นฐาน 2','Fundamentals of Nursing 2',2,'2(1-2-3)','หลักการและเทคนิคการทำหัตถการทางการพยาบาลที่ซับซ้อนขึ้น การวัดสัญญาณชีพ การเก็บสิ่งส่งตรวจ การให้ออกซิเจน การดูดเสมหะ การแต่งแผล หลักเกณฑ์ความปลอดภัยในการบริหารยา และการฝึกปฏิบัติในห้องปฏิบัติการ',1,1,NULL,'หมวดวิชาเฉพาะ',2,2),(34,'170-216','เภสัชวิทยาทางการพยาบาล','Pharmacology in Nursing',2,'2(2-0-4)','กลไกการออกฤทธิ์ เภสัชจลนศาสตร์ ข้อบ่งใช้ ผลข้างเคียง และข้อควรระวังของยาในกลุ่มต่างๆ บทบาทหน้าที่ของพยาบาลในการบริหารยาอย่างปลอดภัย การคำนวณขนาดยา และการพยาบาลผู้ป่วยที่ได้รับยา',1,1,NULL,'หมวดวิชาเฉพาะ',2,1),(35,'170-222','จรรยาบรรณวิชาชีพการพยาบาลและกฎหมายที่เกี่ยวข้อง','Nursing Ethics and Related Laws',2,'2(2-0-4)','แนวคิดทางจริยธรรม จรรยาบรรณวิชาชีพพยาบาล สิทธิผู้ป่วย กฎหมายวิชาชีพการพยาบาลและผดุงครรภ์ และกฎหมายสาธารณสุขที่เกี่ยวข้องกับการปฏิบัติการพยาบาล การตัดสินใจเชิงจริยธรรมในสถานการณ์ปัญหาขัดแย้ง',1,1,NULL,'หมวดวิชาเฉพาะ',2,2),(36,'170-224','ชีวสถิติทางสุขภาพ','Biostatistics for Health',2,'2(2-0-4)','สถิติพรรณนาและสถิติอ้างอิงที่ประยุกต์ใช้ในงานวิทยาศาสตร์สุขภาพ การทดสอบสมมติฐาน การเลือกใช้สถิติที่เหมาะสมในการวิเคราะห์ข้อมูล และการใช้โปรแกรมคอมพิวเตอร์สำเร็จรูปเพื่อการวิเคราะห์และแปลผล',1,1,NULL,'หมวดวิชาเฉพาะ',2,1),(37,'170-228','พัฒนาการมนุษย์และการสร้างเสริมสุขภาพ','Human Development and Health Promotion',2,'2(2-0-4)','ทฤษฎีและพัฒนาการของมนุษย์ในทุกช่วงวัย ปัจจัยที่มีผลต่อการเจริญเติบโต แนวคิดและแนวทางการสร้างเสริมสุขภาพ การป้องกันโรค และการประเมินภาวะสุขภาพตามกลุ่มวัย พฤติกรรมสุขภาพและแบบแผนการดำเนินชีวิต',1,1,NULL,'หมวดวิชาเฉพาะ',2,1),(38,'170-229','โภชนบำบัด','Diet Therapy',2,'2(2-0-4)','หลักโภชนาการปกติและความต้องการสารอาหารในแต่ละวัย หลักการจัดอาหารบำบัดโรคสำหรับผู้ป่วยที่มีพยาธิสภาพต่างๆ เช่น เบาหวาน ความดันโลหิตสูง โรคไต โรคหัวใจ บทบาทพยาบาลในการดูแลและให้คำแนะนำด้านอาหาร',1,1,NULL,'หมวดวิชาเฉพาะ',2,1),(39,'170-226','การพยาบาลผู้ใหญ่','Adult Nursing',3,'3(3-0-6)','การพยาบาลแบบองค์รวมสำหรับผู้ป่วยวัยผู้ใหญ่ที่มีปัญหาสุขภาพในระยะเฉียบพลัน กึ่งเฉียบพลัน และเรื้อรัง ของระบบทางเดินหายใจ ไหลเวียนโลหิต ทางเดินอาหาร ทางเดินปัสสาวะ ต่อมไร้ท่อ และระบบประสาท โดยใช้กระบวนการพยาบาล',1,1,NULL,'หมวดวิชาเฉพาะ',2,2),(40,'170-227','มโนมติ ทฤษฎีการพยาบาล และบริการด้วยหัวใจความเป็นมนุษย์','Concepts, Nursing Theories, and Humanized Care Service',2,'2(2-0-4)','มโนมติหลักทางการพยาบาล วิวัฒนาการของวิชาชีพ ทฤษฎีการพยาบาลที่สำคัญและการนำไปประยุกต์ใช้ในการปฏิบัติ แนวคิดและค่านิยมการบริการด้วยหัวใจความเป็นมนุษย์ ความเอื้ออาทร และการเคารพศักดิ์ศรีความเป็นมนุษย์',1,1,NULL,'หมวดวิชาเฉพาะ',2,2),(41,'170-230','กระบวนการพยาบาลและการประเมินภาวะสุขภาพ','Nursing Process and Health Assessment',2,'2(1-2-3)','ขั้นตอนและองค์ประกอบของกระบวนการพยาบาล หลักการและเทคนิคการประเมินภาวะสุขภาพทางกาย จิต สังคม จิตวิญญาณ การซักประวัติ การตรวจร่างกายทุกระบบ การบันทึกข้อมูลสุขภาพ และการฝึกทักษะการตรวจร่างกาย',1,1,NULL,'หมวดวิชาเฉพาะ',2,2),(42,'170-231','การประยุกต์ใช้ AI และเทคโนโลยีดิจิทัลทางการพยาบาล','Application of AI and Digital Technology in Nursing',2,'2(1-2-3)','แนวคิดและการประยุกต์ใช้ปัญญาประดิษฐ์ (AI) เทคโนโลยีดิจิทัล และสารสนเทศในการจัดการข้อมูลสุขภาพ ระบบบันทึกทางการพยาบาลอิเล็กทรอนิกส์ การพยาบาลทางไกล (Telenursing) และจริยธรรมความปลอดภัยของข้อมูล',1,1,NULL,'หมวดวิชาเฉพาะ',2,2),(43,'170-324','การพยาบาลผู้สูงอายุ','Gerontological Nursing',2,'2(2-0-4)','กระบวนการชราภาพและการเปลี่ยนแปลงในผู้สูงอายุ กลุ่มอาการที่พบบ่อยในผู้สูงอายุ การประเมินภาวะสุขภาพผู้สูงอายุแบบองค์รวม การพยาบาลผู้สูงอายุที่มีปัญหาสุขภาพเฉียบพลันและเรื้อรัง และการดูแลในระยะท้าย',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(44,'170-348','การพยาบาลเด็กและวัยรุ่น','Pediatric and Adolescent Nursing',3,'3(3-0-6)','การเจริญเติบโต พัฒนาการ และพยาธิสภาพของโรคที่พบบ่อยในทารก เด็ก และวัยรุ่น การประยุกต์ใช้กระบวนการพยาบาลในการดูแลเด็กที่มีภาวะเจ็บป่วยเฉียบพลัน เรื้อรัง และวิกฤต โดยเน้นครอบครัวเป็นศูนย์กลาง',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(45,'170-349','การพยาบาลวิกฤตและฉุกเฉิน','Critical Care and Emergency Nursing',2,'2(2-0-4)','หลักการพยาบาลในภาวะฉุกเฉินและวิกฤตคุกคามต่อชีวิต การคัดแยกผู้ป่วย การประเมินและเฝ้าระวังอาการอย่างรวดเร็วต่อเนื่อง พยาธิสภาพของผู้ป่วยภาวะช็อก บาดเจ็บรุนแรงหลายระบบ และหลักการช่วยฟื้นคืนชีพขั้นสูง',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(46,'170-350','การพยาบาลสุขภาพจิตและจิตเวชศาสตร์','Psychiatric and Mental Health Nursing',3,'3(3-0-6)','แนวคิด ทฤษฎี และลักษณะทางคลินิกของโรคทางจิตเวชที่พบบ่อย ปัจจัยที่มีผลต่อสุขภาพจิต การประยุกต์ใช้กระบวนการพยาบาลในการดูแลแบบองค์รวมแก่ผู้รับบริการที่มีปัญหาสุขภาพจิต การบำบัดทางการพยาบาลจิตเวช',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(47,'170-351','การพยาบาลมารดาและทารก','Maternal and Newborn Nursing',3,'3(3-0-6)','แนวคิดและทฤษฎีการพยาบาลในการดูแลสตรีในระยะตั้งครรภ์ ระยะคลอด และระยะหลังคลอดปกติ พยาธิสรีรวิทยาและการเปลี่ยนแปลงตามธรรมชาติ การประเมินสุขภาพมารดาและทารกในครรภ์ กลไกการคลอด และการบริบาลทารกแรกเกิด',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(48,'170-352','การผดุงครรภ์','Midwifery',3,'3(3-0-6)','กฎหมายและขอบเขตวิชาชีพผดุงครรภ์ การพยาบาลและการผดุงครรภ์ในสตรีที่มีภาวะแทรกซ้อนในระยะตั้งครรภ์ ระยะคลอด และระยะหลังคลอด ทารกแรกเกิดที่มีภาวะเสี่ยงหรือพยาธิสภาพ การเฝ้าระวังและการพยาบาลในภาวะฉุกเฉิน',1,1,NULL,'หมวดวิชาเฉพาะ',3,2),(49,'170-353','การพยาบาลอนามัยชุมชน','Community Health Nursing',3,'3(3-0-6)','หลักการสาธารณสุขและการพยาบาลอนามัยชุมชน ระบบบริการสุขภาพปฐมภูมิ เครื่องมือศึกษาชุมชน การประเมินและการวางแผนแก้ปัญหาอนามัยชุมชน การประยุกต์ใช้กระบวนการพยาบาลในการดูแลครอบครัวและกลุ่มเฉพาะ',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(50,'170-354','กระบวนการวิจัยทางวิชาชีพ','Professional Research Process',2,'2(2-0-4)','ความสำคัญของการวิจัยทางการพยาบาล จริยธรรมการวิจัยในมนุษย์ ขั้นตอนกระบวนการวิจัย ตั้งแต่การกำหนดปัญหาวิจัย การทบทวนวรรณกรรม รูปแบบการวิจัย เครื่องมือ การเก็บรวบรวมข้อมูล และการวิเคราะห์แปลผลข้อมูล',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(51,'170-448','การรักษาพยาบาลเบื้องต้น','Primary Medical Care',2,'2(2-0-4)','หลักการและขอบเขตการรักษาพยาบาลเบื้องต้นโดยพยาบาลตามกฎหมาย การซักประวัติ ตรวจร่างกาย และใช้เหตุผลทางคลินิกเพื่อวินิจฉัยแยกโรค อาการเจ็บป่วยและโรคที่พบบ่อย การสั่งใช้ยาตามขอบเขตวิชาชีพ และการส่งต่อ',1,1,NULL,'หมวดวิชาเฉพาะ',4,1),(52,'170-457','ภาวะผู้นำและการบริหารทางการพยาบาล','Leadership and Nursing Management',2,'2(2-0-4)','แนวคิดทฤษฎีภาวะผู้นำ การจัดการองค์กรพยาบาล กระบวนการบริหารจัดการทางการพยาบาล (วางแผน จัดองค์กร บริหารงานบุคคล อำนวยการ ควบคุม) การประกันคุณภาพการพยาบาล การบริหารความเสี่ยงและความขัดแย้ง',1,1,NULL,'หมวดวิชาเฉพาะ',4,1),(53,'170-232','ปฏิบัติการพยาบาลพื้นฐาน','Practicum in Fundamentals of Nursing',2,'2(0-8-0)','การฝึกปฏิบัติการพยาบาลบนหอผู้ป่วยในการดูแลผู้ป่วยที่มีความต้องการขั้นพื้นฐาน โดยใช้กระบวนการพยาบาลและทักษะหัตถการพื้นฐาน การสื่อสารเพื่อการบำบัด ความปลอดภัย การบริหารยา และการบันทึกรายงาน',1,1,NULL,'หมวดวิชาเฉพาะ',2,2),(54,'170-327','ปฏิบัติการสุขภาพจิตและจิตเวชศาสตร์','Practicum in Psychiatric and Mental Health Nursing',2,'2(0-8-0)','การฝึกปฏิบัติการพยาบาลในการดูแลผู้รับบริการที่มีปัญหาสุขภาพจิตและโรคทางจิตเวช การสร้างสัมพันธภาพและการสื่อสารเพื่อการบำบัดรายบุคคลและกลุ่ม กิจกรรมบำบัด การบริหารยาจิตเวช และการคุ้มครองสิทธิผู้ป่วย',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(55,'170-331','ปฏิบัติการพยาบาลเด็กและวัยรุ่น','Practicum in Pediatric Nursing',2,'2(0-8-0)','การฝึกปฏิบัติการพยาบาลในการดูแลทารก เด็ก และวัยรุ่น ที่มีภาวะเจ็บป่วยเฉียบพลัน เรื้อรัง และวิกฤต ในหอผู้ป่วยเด็ก โดยใช้กระบวนการพยาบาล การประเมินภาวะสุขภาพและพัฒนาการ และการบริหารยาอย่างปลอดภัย',1,1,NULL,'หมวดวิชาเฉพาะ',3,2),(56,'170-337','ปฏิบัติการพยาบาลมารดาและทารก','Practicum in Maternal and Newborn Nursing',2,'2(0-8-0)','การฝึกปฏิบัติการพยาบาลในการดูแลสตรีในระยะตั้งครรภ์ ระยะคลอด ระยะหลังคลอดปกติและมีความเสี่ยง และการดูแลทารกแรกเกิดในแผนกฝากครรภ์ ห้องคลอด และหอผู้ป่วยหลังคลอด โดยใช้กระบวนการพยาบาลและการทำคลอดปกติ',1,1,NULL,'หมวดวิชาเฉพาะ',3,2),(57,'170-338','ปฏิบัติการผดุงครรภ์ 1','Practicum in Midwifery 1',2,'2(0-8-0)','การฝึกปฏิบัติการผดุงครรภ์ในการตรวจครรภ์ การทำคลอดปกติ การดูแลทารกแรกเกิดทันทีหลังคลอด การเย็บแผลฝีเย็บ และการดูแลมารดาและทารกในระยะหลังคลอดปกติ ตามขอบเขตมาตรฐานวิชาชีพ',1,1,NULL,'หมวดวิชาเฉพาะ',3,2),(58,'170-339','ปฏิบัติการพยาบาลผู้ใหญ่และผู้สูงอายุ','Practicum in Adult and Gerontological Nursing',4,'4(0-16-0)','การฝึกปฏิบัติการพยาบาลในการดูแลผู้ป่วยวัยผู้ใหญ่และผู้สูงอายุที่มีปัญหาสุขภาพเฉียบพลันและเรื้อรัง โดยประยุกต์ใช้กระบวนการพยาบาลแบบองค์รวม ทักษะหัตถการที่ซับซ้อนอย่างปลอดภัย และการเฝ้าระวังอาการ',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(59,'170-340','ปฏิบัติการพยาบาลผู้ป่วยวิกฤตและฉุกเฉิน','Practicum in Critical Care and Emergency Nursing',2,'2(0-8-0)','การฝึกปฏิบัติการพยาบาลใน ICU หรือ ER ในการดูแลผู้ป่วยภาวะวิกฤตหรือฉุกเฉินคุกคามต่อชีวิต การประเมินและเฝ้าระวังอาการอย่างรวดเร็วต่อเนื่อง การกู้ชีพขั้นสูง และการใช้เทคโนโลยีขั้นสูงในการดูแลผู้ป่วย',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(60,'170-355','ปฏิบัติการพยาบาลอนามัยชุมชน','Practicum in Community Health Nursing',2,'2(0-8-0)','การฝึกปฏิบัติการพยาบาลอนามัยชุมชน การใช้เครื่องมือและกระบวนการศึกษาชุมชน การจัดทำโครงการพัฒนาสุขภาพร่วมกับชุมชน การจัดกิจกรรมสร้างเสริมสุขภาพ การป้องกันโรค และการฝึกปฏิบัติการพยาบาลที่บ้าน',1,1,NULL,'หมวดวิชาเฉพาะ',3,2),(61,'170-431','ปฏิบัติการผดุงครรภ์ 2','Practicum in Midwifery 2',2,'2(0-8-0)','การฝึกปฏิบัติการผดุงครรภ์ในการดูแลมารดาและทารกในระยะตั้งครรภ์ ระยะคลอด และระยะหลังคลอดที่มีภาวะแทรกซ้อนหรือความเสี่ยงสูง การช่วยเหลือเบื้องต้นในภาวะฉุกเฉินทางสูติศาสตร์อย่างถูกต้องปลอดภัย',1,1,NULL,'หมวดวิชาเฉพาะ',4,1),(62,'170-449','ปฏิบัติการรักษาพยาบาลเบื้องต้น','Practicum in Primary Medical Care',2,'2(0-8-0)','การฝึกปฏิบัติการรักษาพยาบาลเบื้องต้นในหน่วยบริการปฐมภูมิหรือ ER/OPD ทักษะการซักประวัติ ตรวจร่างกาย วินิจฉัยแยกโรคเบื้องต้น สั่งใช้ยาตามขอบเขต การทำหัตถการเย็บแผล ล้างแผล ถอดเล็บ และการส่งต่อผู้ป่วย',1,1,NULL,'หมวดวิชาเฉพาะ',4,1),(63,'170-458','ปฏิบัติการจัดการพยาบาล','Practicum in Nursing Management',2,'2(0-8-0)','การฝึกปฏิบัติการบริหารจัดการทางการพยาบาลบนหอผู้ป่วยในฐานะหัวหน้าเวร ทักษะภาวะผู้นำ การมอบหมายงาน การนิเทศการพยาบาล การบริหารความเสี่ยง คุมคุณภาพการพยาบาล และการทำงานร่วมกับสหสาขาวิชาชีพ',1,1,NULL,'หมวดวิชาเฉพาะ',4,2),(64,'170-459','ปฏิบัติการพยาบาลรวบยอดวิกฤตและฉุกเฉิน','Comprehensive Practicum in Critical Care and Emergency Nursing',3,'3(0-12-0)','การฝึกปฏิบัติการพยาบาลรวบยอดในสภาวะวิกฤตและฉุกเฉิน บูรณาการองค์ความรู้ ทฤษฎี และงานวิจัยเชิงประจักษ์ในการดูแลผู้ป่วยวิกฤตและฉุกเฉินที่มีความซับซ้อนสูง เพื่อเตรียมความพร้อมสู่การเป็นพยาบาลวิชาชีพ',1,1,NULL,'หมวดวิชาเฉพาะ',4,2),(65,'170-114','เคมีอินทรีย์พื้นฐาน','Basic Organic Chemistry',2,'2(2-0-4)','โครงสร้าง การเรียกชื่อ ไอโซเมอริซึม และปฏิกิริยาเคมีของสารประกอบอินทรีย์กลุ่มต่างๆ ที่มีความสำคัญทางชีวภาพและทางการแพทย์',1,1,NULL,'หมวดวิชาเฉพาะ',1,1),(66,'170-115','ฟิสิกส์การแพทย์เบื้องต้น','Introduction to Medical Physics',2,'2(2-0-4)','หลักการทางฟิสิกส์ที่ประยุกต์ใช้ในทางการแพทย์ เช่น กลศาสตร์ของของไหลในระบบหมุนเวียน คลื่นเสียงและอัลตราซาวด์ รังสีและการป้องกันรังสี',1,1,NULL,'หมวดวิชาเฉพาะ',1,2),(67,'170-235','พันธุศาสตร์ทางการแพทย์และจีโนมิกส์','Medical Genetics and Genomics',2,'2(2-0-4)','การถ่ายทอดลักษณะทางพันธุกรรม โครงสร้างดีเอ็นเอ ความผิดปกติของโครโมโซม โรคทางพันธุกรรมที่พบบ่อย และแนวคิดจีโนมิกส์ในการรักษาแบบแม่นยำ',1,1,NULL,'หมวดวิชาเฉพาะ',2,1),(68,'170-236','วิทยาภูมิคุ้มกันพื้นฐาน','Basic Immunology',2,'2(2-0-4)','กลไกการตอบสนองทางภูมิคุ้มกันของร่างกาย ทั้งแบบจำเพาะและไม่จำเพาะ อวัยวะและเซลล์ในระบบภูมิคุ้มกัน ความผิดปกติของระบบภูมิคุ้มกันและการแพ้ยา',1,1,NULL,'หมวดวิชาเฉพาะ',2,2),(69,'170-356','การพยาบาลบรรเทาอาการและดูแลระยะท้าย','Palliative and End-of-Life Care',2,'2(2-0-4)','หลักการดูแลแบบประคับประคอง การจัดการความปวดและอาการทุกข์ทรมาน การสนับสนุนทางจิตสังคมและจิตวิญญาณแก่ผู้ป่วยระยะท้ายและครอบครัว',1,1,NULL,'หมวดวิชาเฉพาะ',3,2),(70,'170-357','สารสนเทศศาสตร์สุขภาพ','Health Informatics',2,'2(1-2-3)','ระบบข้อมูลสารสนเทศในโรงพยาบาล มาตรฐานรหัสทางการแพทย์ การจัดการฐานข้อมูลสุขภาพ และแนวโน้มเทคโนโลยีสารสนเทศสุขภาพในอนาคต',1,1,NULL,'หมวดวิชาเฉพาะ',3,1),(71,'170-460','การเตรียมความพร้อมเพื่อการทำงานในอนาคต','Preparation for Future Career',1,'1(0-2-1)','การพัฒนาบุคลิกภาพ เทคนิคการสมัครงานและการสัมภาษณ์ ภาษาอังกฤษเพื่อการทำงาน จริยธรรมในการทำงาน และการวางแผนเส้นทางอาชีพในอนาคต',1,1,NULL,'หมวดวิชาเฉพาะ',4,1),(72,'170-461','การประมวลความรู้ทางวิชาชีพการพยาบาล','Comprehensive Review of Professional Nursing',2,'2(2-0-4)','การทบทวนและประมวลความรู้รวบยอดในศาสตร์ทางการพยาบาลทุกสาขาวิชา เพื่อเตรียมความพร้อมในการสอบขึ้นทะเบียนรับใบอนุญาตประกอบวิชาชีพ',1,1,NULL,'หมวดวิชาเฉพาะ',4,2),(73,'170-462','การฝึกปฏิบัติการพยาบาลเลือกสรร','Elective Practicum in Nursing',2,'2(0-8-0)','การเลือกฝึกปฏิบัติงานในหอผู้ป่วยหรือสาขาวิชาที่นักศึกษาสนใจเป็นพิเศษ เพื่อเพิ่มพูนทักษะและความมั่นใจก่อนจบการศึกษาเป็นพยาบาลวิชาชีพ',1,1,NULL,'หมวดวิชาเฉพาะเลือก',4,2);
