--
-- Table structure for table `system_sidebar_menus`
--

DROP TABLE IF EXISTS `system_sidebar_menus`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
